{"path": "/tmp/sv-01283ccadc154222b3e414974dc9ecda/Components/Catalog/CatalogPagination.razor", "file_text": "@if (TotalPages > 1)
{
    <nav class="catalog-pagination">
        <button class="page-btn"
                disabled="@(CurrentPage <= 1)"
                @onclick="() => ChangePage(CurrentPage - 1)">
            Previous
        </button>

        @for (int i = 1; i <= TotalPages; i++)
        {
            var pageNum = i;
            <button class="page-btn @(pageNum == CurrentPage ? "active" : "")"
                    @onclick="() => ChangePage(pageNum)">
                @pageNum
            </button>
        }

        <button class="page-btn"
                disabled="@(CurrentPage >= TotalPages)"
                @onclick="() => ChangePage(CurrentPage + 1)">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int CurrentPage { get; set; }

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int PageSize { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private int TotalPages => PageSize > 0 ? (int)Math.Ceiling((double)TotalCount / PageSize) : 0;

    private async Task ChangePage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}
"}

