@@ -1,0 +1,87 @@
+<aside class="catalog-filters">
+    <h4>Filters</h4>
+
+    <div class="filter-section">
+        <h5>Categories</h5>
+        @if (Categories is not null)
+        {
+            @foreach (var category in Categories)
+            {
+                <label class="checkbox-label">
+                    <input type="checkbox"
+                           checked="@IsSelected(category)"
+                           @onchange="() => ToggleCategory(category)" />
+                    @category
+                </label>
+            }
+        }
+    </div>
+
+    <div class="filter-section">
+        <h5>Price Range</h5>
+        <div class="price-inputs">
+            <input type="number" placeholder="Min" @bind="minPrice" min="0" step="0.01" />
+            <span>–</span>
+            <input type="number" placeholder="Max" @bind="maxPrice" min="0" step="0.01" />
+        </div>
+    </div>
+
+    <div class="filter-section">
+        <label class="checkbox-label">
+            <input type="checkbox" @bind="inStockOnly" />
+            In Stock Only
+        </label>
+    </div>
+
+    <div class="filter-actions">
+        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
+        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
+    </div>
+</aside>
+
+@code {
+    [Parameter, EditorRequired]
+    public List<string> Categories { get; set; } = new();
+
+    [Parameter]
+    public EventCallback<ProductFilter> OnFilterApplied { get; set; }
+
+    [Parameter]
+    public EventCallback OnFilterCleared { get; set; }
+
+    private List<string> selectedCategories = new();
+    private decimal? minPrice;
+    private decimal? maxPrice;
+    private bool inStockOnly;
+
+    private bool IsSelected(string category) => selectedCategories.Contains(category);
+
+    private void ToggleCategory(string category)
+    {
+        if (selectedCategories.Contains(category))
+            selectedCategories.Remove(category);
+        else
+            selectedCategories.Add(category);
+    }
+
+    private async Task ApplyFilters()
+    {
+        var filter = new ProductFilter(
+            Categories: selectedCategories.Count > 0 ? new List<string>(selectedCategories) : null,
+            MinPrice: minPrice,
+            MaxPrice: maxPrice,
+            InStockOnly: inStockOnly
+        );
+        await OnFilterApplied.InvokeAsync(filter);
+    }
+
+    private async Task ClearFilters()
+    {
+        selectedCategories.Clear();
+        minPrice = null;
+        maxPrice = null;
+        inStockOnly = false;
+        await OnFilterCleared.InvokeAsync();
+    }
+}
+

