.catalog-filters {
    padding: 1rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    background-color: #fafafa;
}

.catalog-filters h4 {
    margin: 0 0 1rem 0;
    font-size: 1.2rem;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h5 {
    margin: 0 0 0.5rem 0;
    font-size: 0.9rem;
    color: #555;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.4rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.price-inputs {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.price-inputs input {
    width: 80px;
    padding: 0.4rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.9rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply {
    padding: 0.5rem 1rem;
    background-color: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
}

.btn-apply:hover {
    background-color: #0b5ed7;
}

.btn-clear {
    padding: 0.5rem 1rem;
    background-color: transparent;
    color: #6c757d;
    border: 1px solid #6c757d;
    border-radius: 4px;
    cursor: pointer;
}

.btn-clear:hover {
    background-color: #f8f9fa;
}

