toolArgs.file_text:
@page "/catalog"
@using sv_01283ccadc154222b3e414974dc9ecda.Components.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h2>Product Catalog</h2>

@if (errorMessage is not null)
{
    <div class="error-banner">
        <p>@errorMessage</p>
        <button @onclick="LoadProducts">Retry</button>
    </div>
}
else
{
    <div class="catalog-layout">
        <div class="catalog-sidebar">
            <CatalogFilters Categories="categories"
                            OnFilterApplied="HandleFilterApplied"
                            OnFilterCleared="HandleFilterCleared" />
        </div>
        <div class="catalog-main">
            @if (isLoading)
            {
                <div class="loading-indicator">
                    <p>Loading products...</p>
                </div>
            }
            else if (pagedResult is not null)
            {
                <CatalogToolbar SortBy="@sortBy"
                                TotalCount="pagedResult.TotalCount"
                                Page="currentPage"
                                PageSize="pageSize"
                                OnSortChanged="HandleSortChanged" />

                <ProductGrid Products="pagedResult.Items"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />

                <CatalogPagination CurrentPage="currentPage"
                                   TotalCount="pagedResult.TotalCount"
                                   PageSize="pageSize"
                                   OnPageChanged="HandlePageChanged" />
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string> categories = new();
    private PagedResult<Product>? pagedResult;
    private ProductFilter currentFilter = new(null, null, null, false);
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private bool isLoading;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
            await LoadProducts();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load catalog: {ex.Message}";
        }
    }

    private async Task LoadProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            StateHasChanged();

            pagedResult = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        currentFilter = filter;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleFilterCleared()
    {
        currentFilter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string newSort)
    {
        sortBy = newSort;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

